    condition: pInit?.condition || 'Post-Stroke Left Hemiparesis',
    target_hand: pInit?.target_hand || 'right',
    protocol: pInit?.protocol || 'Active Pronation / Supination',
    functional_stage: pInit?.functional_stage || 'Brunnstrom Stage IV - Moderate Spasticity',
